281	fn readMessageOptional(self: *StreamReader) (StreamError || fbs_lite_builder.PackError || std.Io.Reader.Error || error{ EndOfStream, OutOfMemory })!?MessageWithBody {
282	    const meta_len_opt = try format.readMessageLength(self.reader);
283	    if (meta_len_opt == null) return null;
284	    const meta_len = meta_len_opt.?;
285	
286	    var meta_buf_owned = try OwnedBuffer.init(self.allocator, meta_len);
287	    errdefer meta_buf_owned.deinit();
288	    if (meta_len > 0) try self.reader.readSliceAll(meta_buf_owned.data[0..meta_len]);
289	    var metadata = try meta_buf_owned.toShared(meta_len);
290	    errdefer metadata.release();
291	    try format.skipPadding(self.reader, format.padLen(meta_len));
292	
293	    const envelope = fbs_lite_verify.parseArrowMessageEnvelope(metadata.data) catch return StreamError.InvalidMetadata;
294	
295	    const msg_t = try fbs_lite_builder.unpackMessage(self.allocator, metadata.data);
296	    errdefer {
297	        var tmp = msg_t;
298	        tmp.deinit(self.allocator);
299	    }
300	    if (!isSupportedMetadataVersion(msg_t.version)) return StreamError.InvalidMetadata;
301	
302	    var body_shared: ?array_data.SharedBuffer = null;
303	    const body_len = std.math.cast(usize, envelope.body_length) orelse return StreamError.InvalidBody;
304	    if (body_len > 0) {
305	        var body_buf = try OwnedBuffer.init(self.allocator, body_len);
306	        errdefer body_buf.deinit();
307	        try self.reader.readSliceAll(body_buf.data[0..body_len]);
308	        body_shared = try body_buf.toShared(body_len);
309	    }
310	    try format.skipPadding(self.reader, format.padLen(body_len));
311	
312	    return .{ .metadata = metadata, .msg = msg_t, .body_len = body_len, .body = body_shared };
313	}
