1143	    errdefer if (!schema_taken) mut_ref.release();
1144	    const schema = schema_ref.schema();
1145	    const columns = try allocator.alloc(ArrayRef, schema.fields.len);
1146	    var col_count: usize = 0;
1147	    errdefer {
1148	        var i: usize = 0;
