1166	            decoded.body,
1167	            &node_index,
1168	            &buffer_index,
1169	            &variadic_index,
1170	            dictionary_values,
1171	            metadata_version,
1172	        );
1173	        col_count += 1;
1174	    }
1175	    if (node_index != record_batch_t.nodes.items.len or buffer_index != decoded.buffers_meta.len) {
1176	        return StreamError.InvalidMetadata;
1177	    }
