1423	fn validateV4UnionValidityBuffer(validity: array_data.SharedBuffer, length: usize, null_count: usize) StreamError!void {
1424	    if (null_count != 0) return StreamError.UnsupportedType;
1425	    if (length == 0 or validity.isEmpty()) return;
1426	    if (validity.len() < bitmap.byteLength(length)) return StreamError.InvalidMetadata;
1427	
1428	    const validity_bitmap = bitmap.ValidityBitmap.fromBuffer(validity, length);
1429	    var i: usize = 0;
1430	    while (i < length) : (i += 1) {
1431	        const is_valid = validity_bitmap.isValid(i) catch return StreamError.InvalidMetadata;
1432	        if (!is_valid) return StreamError.UnsupportedType;
1433	    }
1434	}
