1475	fn canReuseBodySlice(body: array_data.SharedBuffer, start: usize, required_alignment: usize) bool {
1476	    if (body.storage == null) return false;
1477	    if (required_alignment <= 1) return true;
1478	    const addr = @intFromPtr(body.data.ptr) + start;
1479	    return (addr & (required_alignment - 1)) == 0;
1480	}
