1502	        .sparse_union => if (metadataVersionUsesV4UnionLayout(metadata_version)) 2 else 1,
1503	        .dense_union => if (metadataVersionUsesV4UnionLayout(metadata_version)) 3 else 2,
1504	        .run_end_encoded => 0,
1505	        else => StreamError.UnsupportedType,
