235	    pub fn nextTensorLikeMessage(self: *Self) (StreamError || fbs_lite_builder.PackError || std.Io.Reader.Error || error{ EndOfStream, OutOfMemory })!?OwnedTensorLikeMessage {
236	        while (true) {
237	            const maybe_msg = try readMessageOptional(self);
238	            if (maybe_msg == null) return null;
239	            var msg = maybe_msg.?;
240	            defer msg.deinit(self.allocator);
241	
242	            if (msg.body == null) {
243	                if (msg.msg.header == .Tensor or msg.msg.header == .SparseTensor) return StreamError.InvalidBody;
244	                continue;
245	            }
246	
247	            switch (msg.msg.header) {
248	                .Tensor, .SparseTensor => {
249	                    var arena = std.heap.ArenaAllocator.init(self.allocator);
250	                    errdefer arena.deinit();
251	                    const meta = try decodeTensorLikeFromUnpackedMessage(
252	                        arena.allocator(),
253	                        msg.msg,
254	                        msg.body.?,
255	                    );
256	                    return .{
257	                        .arena = arena,
258	                        .metadata = meta,
259	                        .body = msg.body.?.retain(),
260	                    };
261	                },
262	                else => continue,
263	            }
264	        }
265	    }
