1140	    // schema_ref is already retained by the caller; track it so early‑error paths release it.
1141	    var schema_taken = false;
1142	    var mut_ref = schema_ref;
1143	    errdefer if (!schema_taken) mut_ref.release();
1144	    const schema = schema_ref.schema();
1145	    const columns = try allocator.alloc(ArrayRef, schema.fields.len);
1146	    var col_count: usize = 0;
1147	    errdefer {
1148	        var i: usize = 0;
1149	        while (i < col_count) : (i += 1) columns[i].release();
1150	        allocator.free(columns);
