1165	            record_batch_t.variadicBufferCounts.items,
1166	            decoded.body,
1167	            &node_index,
1168	            &buffer_index,
1169	            &variadic_index,
1170	            dictionary_values,
1171	            metadata_version,
1172	        );
1173	        col_count += 1;
1174	    }
1175	    if (node_index != record_batch_t.nodes.items.len or buffer_index != decoded.buffers_meta.len) {
1176	        return StreamError.InvalidMetadata;
1177	    }
1178	    if (variadic_index != record_batch_t.variadicBufferCounts.items.len) return StreamError.InvalidMetadata;
1179	
1180	    const batch = try RecordBatch.init(allocator, mut_ref, columns);
1181	    // RecordBatch.init succeeded and owns mut_ref now; cancel the schema errdefer.
1182	    schema_taken = true;
