1436	fn requiredBufferAlignment(dt: DataType, buffer_idx: usize, metadata_version: fbs.MetadataVersion) usize {
1437	    const layout_dt = storageDataType(dt);
1438	    if (metadataVersionUsesV4UnionLayout(metadata_version)) {
1439	        switch (layout_dt) {
1440	            .sparse_union => return if (buffer_idx == 0) @alignOf(u8) else @alignOf(i8),
1441	            .dense_union => return switch (buffer_idx) {
1442	                0 => @alignOf(u8),
1443	                1 => @alignOf(i8),
1444	                else => @alignOf(i32),
1445	            },
1446	            else => {},
1447	        }
1448	    }
1449	
1450	    if (hasTopLevelValidityBitmap(layout_dt)) {
1451	        if (buffer_idx == 0) return @alignOf(u8);
1452	        const value_idx = buffer_idx - 1;
1453	        return switch (layout_dt) {
1454	            .bool => @alignOf(u8),
1455	            .uint8, .int8, .uint16, .int16, .uint32, .int32, .uint64, .int64, .half_float, .float, .double, .fixed_size_binary, .date32, .date64, .time32, .time64, .timestamp, .duration, .interval_months, .interval_day_time, .interval_month_day_nano, .decimal32, .decimal64, .decimal128, .decimal256 => primitiveValueAlignment(layout_dt),
