1457	            .large_string, .large_binary => if (value_idx == 0) @alignOf(i64) else @alignOf(u8),
1458	            .list, .map => @alignOf(i32),
1459	            .large_list => @alignOf(i64),
1460	            .list_view => @alignOf(i32),
1461	            .large_list_view => @alignOf(i64),
1462	            .dictionary => alignmentForIntType(layout_dt.dictionary.index_type),
1463	            .struct_, .fixed_size_list => @alignOf(u8),
1464	            else => @alignOf(u8),
1465	        };
1466	    }
1467	
1468	    return switch (layout_dt) {
1469	        .sparse_union => @alignOf(i8),
1470	        .dense_union => if (buffer_idx == 0) @alignOf(i8) else @alignOf(i32),
1471	        else => @alignOf(u8),
1472	    };
