1482	fn bufferCountForType(
1483	    dt: DataType,
1484	    variadic_buffer_counts: []const i64,
1485	    variadic_index: *usize,
1486	    metadata_version: fbs.MetadataVersion,
1487	) StreamError!usize {
1488	    return switch (storageDataType(dt)) {
1489	        .null => 0,
1490	        .struct_, .fixed_size_list => 1,
1491	        .list, .large_list, .map => 2,
1492	        .list_view, .large_list_view => 3,
1493	        .string, .binary, .large_string, .large_binary => 3,
1494	        .string_view, .binary_view => blk: {
1495	            if (variadic_index.* >= variadic_buffer_counts.len) return StreamError.InvalidMetadata;
1496	            const variadic_count = std.math.cast(usize, variadic_buffer_counts[variadic_index.*]) orelse return StreamError.InvalidMetadata;
