39	/// Reference-counted, read-only view over a contiguous byte region.
40	///
41	/// Ownership model:
42	/// - When `storage` is non-null the view is *owning*: `retain`/`release` manage
43	///   the shared reference count and free the backing allocation on last release.
44	/// - When `storage` is null the view is *borrowed*: callers must ensure the
45	///   pointed-to memory outlives all `SharedBuffer` handles derived from it.
46	///
47	/// Slicing (`slice`) produces a new owning handle sharing the same storage.
48	pub const SharedBuffer = struct {
49	    /// Shared control block. `null` for borrowed (non-owning) views.
50	    storage: ?*BufferStorage,
51	    /// Logical byte window for this handle; may be a sub-slice of `storage.data`.
52	    data: []const u8,
53	
54	    const Self = @This();
55	
56	    /// Recoverable errors returned by `slice` and `typedSlice`.
57	    pub const Error = error{
58	        /// Invalid slice range: `start > end` or `end > self.data.len`.
59	        SliceOutOfBounds,
60	        /// `typedSlice(T)` requires pointer alignment compatible with `@alignOf(T)`.
61	        MisalignedPointer,
62	        /// `typedSlice(T)` requires byte length to be a multiple of `@sizeOf(T)`.
63	        LengthNotMultipleOfTypeSize,
64	    };
65	
66	    /// Zero-length borrowed buffer that can be used as a sentinel or placeholder.
67	    pub const empty: SharedBuffer = .{ .storage = null, .data = &.{} };
68	
69	    /// Build a borrowed non-owning shared buffer view from an existing slice.
70	    pub fn fromSlice(data: []const u8) SharedBuffer {
71	        return .{ .storage = null, .data = data };
72	    }
73	
74	    /// Increment shared ownership and return another handle.
75	    pub fn retain(self: Self) Self {
76	        if (self.storage) |storage| {
77	            _ = storage.ref_count.fetchAdd(1, .monotonic);
78	        }
79	        return self;
80	    }
81	
82	    /// Release one ownership reference and cleanup if this is the last handle.
83	    pub fn release(self: *Self) void {
84	        if (self.storage) |storage| {
85	            if (storage.ref_count.fetchSub(1, .acq_rel) == 1) {
86	                storage.release_fn(storage);
87	            }
88	        }
89	        self.storage = null;
90	        self.data = &.{};
91	    }
92	
93	    /// Return the logical length.
94	    pub fn len(self: Self) usize {
95	        return self.data.len;
96	    }
97	
98	    /// Return `true` when the logical length is zero.
99	    pub inline fn isEmpty(self: Self) bool {
100	        return self.data.len == 0;
101	    }
102	
103	    /// Create a logical slice view over the current value.
104	    pub fn slice(self: Self, start: usize, end: usize) Error!Self {
105	        if (start > end or end > self.data.len) {
106	            return Error.SliceOutOfBounds;
107	        }
108	        const out = Self{ .storage = self.storage, .data = self.data[start..end] };
109	
110	        if (out.storage) |storage| {
111	            _ = storage.ref_count.fetchAdd(1, .monotonic);
112	        }
113	        return out;
114	    }
115	
116	    /// Reinterpret raw bytes as a typed immutable slice.
117	    /// Returns an error when pointer alignment or byte-length constraints are not met.
118	    pub fn typedSlice(self: Self, comptime T: type) Error![]const T {
119	        comptime {
120	            if (@sizeOf(T) == 0) @compileError("typedSlice does not support zero-sized types");
121	        }
122	        if (!std.mem.isAligned(@intFromPtr(self.data.ptr), @alignOf(T))) {
123	            return Error.MisalignedPointer;
124	        }
125	        if (self.data.len % @sizeOf(T) != 0) {
126	            return Error.LengthNotMultipleOfTypeSize;
127	        }
128	        const aligned: []align(@alignOf(T)) const u8 = @alignCast(self.data);
129	        return std.mem.bytesAsSlice(T, aligned);
130	    }
131	};
