3	pub const StreamError = error{
4	    InvalidMessage,
5	    UnsupportedType,
6	    SchemaNotRead,
7	    InvalidMetadata,
8	    InvalidBody,
9	};
10	
11	pub const Alignment: usize = 8;
12	pub const ContinuationMarker: u32 = 0xFFFF_FFFF;
13	
14	pub fn paddedLen(len: usize) usize {
15	    return len + padLen(len);
16	}
17	
18	pub fn padLen(len: usize) usize {
19	    const rem = len % Alignment;
20	    return if (rem == 0) 0 else Alignment - rem;
21	}
22	
23	pub fn writeMessageLength(writer: *std.Io.Writer, len: u32) std.Io.Writer.Error!void {
24	    try writeInt(writer, u32, ContinuationMarker);
25	    try writeInt(writer, u32, len);
26	}
27	
28	pub fn readMessageLength(reader: *std.Io.Reader) std.Io.Reader.Error!?u32 {
29	    const first = try readInt(reader, u32);
30	    if (first == 0) return null;
31	    if (first == ContinuationMarker) {
32	        const len = try readInt(reader, u32);
33	        if (len == 0) return null;
34	        return len;
35	    }
36	    return first;
37	}
38	
39	pub fn writePadding(writer: *std.Io.Writer, pad_len: usize) std.Io.Writer.Error!void {
40	    try writer.splatByteAll(0, pad_len);
41	}
42	
43	pub fn skipPadding(reader: *std.Io.Reader, pad_len: usize) std.Io.Reader.Error!void {
44	    try reader.discardAll(pad_len);
45	}
46	
47	pub fn writeInt(writer: *std.Io.Writer, comptime T: type, value: T) std.Io.Writer.Error!void {
48	    try writer.writeInt(T, value, .little);
49	}
50	
51	pub fn readInt(reader: *std.Io.Reader, comptime T: type) std.Io.Reader.Error!T {
52	    // takeInt asserts the reader buffer can hold T; readSliceAll works with unbuffered readers too.
53	    var b: [@sizeOf(T)]u8 = undefined;
54	    try reader.readSliceAll(&b);
55	    return std.mem.readInt(T, &b, .little);
56	}
