129	/// serializes the vtable for the current object, if applicable.
130	///
131	/// Before writing out the vtable, this checks pre-existing vtables for equality
132	/// to this one. If an equal vtable is found, point the object to the existing
133	/// vtable and return.
134	///
135	/// Because vtable values are sensitive to alignment of object data, not all
136	/// logically-equal vtables will be deduplicated.
137	///
138	/// A vtable has the following format:
139	///   <u16: size of the vtable in bytes, including this value>
140	///   <u16: size of the object in bytes, including the vtable offset>
141	///   <u16: offset for a field> * N, where N is the number of fields in
142	///          the schema for this type. Includes deprecated fields.
143	/// Thus, a vtable is made of 2 + N elements, each size_u16 bytes wide.
144	///
145	/// An object has the following format:
146	///   <soff: offset to this object's vtable (may be negative)>
147	///   <byte: data>+
148	pub fn writeVtable(b: *Builder) !u32 {
149	    // Prepend a zero scalar to the object. Later in this function we'll
150	    // write an offset here that points to the object's vtable:
151	    try b.prependSOff(0);
152	
153	    const object_offset = b.offset();
154	    var existing_vtable = @as(u32, 0);
155	
156	    // Trim vtable of trailing zeroes.
157	    {
158	        var i = @as(isize, @bitCast(b.vtable.items.len)) - 1;
159	        while (i >= 0 and b.vtable.items[@as(usize, @bitCast(i))] == 0) : (i -= 1) {}
160	        b.vtable.items.len = @as(usize, @bitCast(i + 1));
161	    }
162	    // Search backwards through existing vtables, because similar vtables
163	    // are likely to have been recently appended. See
164	    // BenchmarkVtableDeduplication for a case in which this heuristic
165	    // saves about 30% of the time used in writing objects with duplicate
166	    // tables.
167	    {
168	        var i = @as(isize, @bitCast(b.vtables.items.len)) - 1;
169	        while (i >= 0) : (i -= 1) {
170	            // Find the other vtable, which is associated with `i`:
171	            const vt2_offset = b.vtables.items[@bitCast(i)];
172	            const vt2_start = b.bytes.items.len - vt2_offset;
173	            const vt2_len = read(u16, b.bytes.items[vt2_start..]);
174	
175	            const metadata = vtable_metadata_fields * size_u16;
176	            const vt2_end = vt2_start + vt2_len;
177	            const vt2 = b.bytes.items[vt2_start + metadata .. vt2_end];
178	
179	            // Compare the other vtable to the one under consideration.
180	            // If they are equal, store the offset and break:
181	            if (vtableEqual(b.vtable.items, object_offset, vt2)) {
182	                existing_vtable = vt2_offset;
183	                break;
184	            }
185	        }
186	    }
187	
188	    if (existing_vtable == 0) {
189	        // Did not find a vtable, so write this one to the buffer.
190	
191	        // Write out the current vtable in reverse , because
192	        // serialization occurs in last-first order:
193	        {
194	            var i = @as(isize, @bitCast(b.vtable.items.len)) - 1;
195	            while (i >= 0) : (i -= 1) {
196	                var off: u32 = 0;
197	                const ii: usize = @bitCast(i);
198	                if (b.vtable.items[ii] != 0) {
199	                    // Forward reference to field;
200	                    // use 32bit number to assert no overflow:
201	                    off = object_offset - b.vtable.items[ii];
202	                }
203	
204	                try b.prepend(u16, @as(u16, @intCast(off)));
205	            }
206	        }
207	        // The two metadata fields are written last.
208	
209	        // First, store the object bytesize:
210	        const object_size = object_offset - b.object_end;
211	        try b.prepend(u16, @as(u16, @intCast(object_size)));
212	
213	        // Second, store the vtable bytesize:
214	        const v_bytes = (b.vtable.items.len + vtable_metadata_fields) * size_u16;
215	        try b.prepend(u16, @as(u16, @intCast(v_bytes)));
216	
217	        // Next, write the offset to the new vtable in the
218	        // already-allocated soff at the beginning of this object:
219	        const object_start = b.bytes.items.len - object_offset;
220	        write(i32, b.bytes.items[object_start..], @as(i32, @intCast(b.offset() -
221	            object_offset)));
222	
223	        // Finally, store this vtable in memory for future
224	        // deduplication:
225	        try b.vtables.append(b.alloc, b.offset());
226	    } else {
227	        // Found a duplicate vtable.
228	
229	        const object_start = @as(u32, @intCast(b.bytes.items.len)) - object_offset;
230	        b.head = object_start;
231	
232	        // Write the offset to the found vtable in the
233	        // already-allocated soff at the beginning of this object:
234	        write(i32, b.bytes.items[b.head..], @as(i32, @bitCast(existing_vtable)) -
235	            @as(i32, @bitCast(object_offset)));
236	    }
237	
238	    b.vtable.items.len = 0;
239	    return object_offset;
240	}
