259	/// Doubles the size of the b.bytes, and copies the old data towards the
260	/// end of the new byteslice (since we build the buffer backwards).
261	pub fn growByteBuffer(b: *Builder) !void {
262	    if ((b.bytes.items.len & 0xC0000000) != 0)
263	        return err(
264	            "cannot grow buffer beyond 2 gigabytes",
265	            .{},
266	            error.OutOfMemory,
267	        );
268	
269	    var new_len = b.bytes.items.len * 2;
270	    if (new_len == 0) new_len = 32;
271	
272	    if (b.bytes.capacity >= new_len)
273	        b.bytes.items.len = new_len
274	    else {
275	        try b.bytes.ensureTotalCapacity(b.alloc, new_len);
276	        b.bytes.items.len = new_len;
277	    }
278	
279	    const middle = new_len / 2;
280	    std.mem.copyForwards(u8, b.bytes.items[middle..], b.bytes.items[0..middle]);
281	}
