475	fn checkFinished(b: *Builder) !void {
476	    // If you get this error, you're attempting to get access a buffer
477	    // which hasn't been finished yet. Be sure to call builder.Finish();
478	    // with your root table.
479	    // If you really need to access an unfinished buffer, use the Bytes
480	    // buffer directly.
481	    if (!b.finished)
482	        return err(
483	            "Incorrect use of finishedBytes(): must call 'finish()' first.",
484	            .{},
485	            error.NotFinished,
486	        );
487	}
