499	/// prepends an u32 onto the object at vtable slot `o`.
500	/// If value `x` equals default `d`, then the slot will be set to zero and no
501	/// other data will be written.
502	pub fn prependSlotUOff(b: *Builder, o: u32, x: u32, d: u32) !void {
503	    if (x != d) {
504	        try b.prependUOff(x);
505	        b.slot(o);
506	    }
507	}
508	
509	// prepends a struct onto the object at vtable slot `o`.
510	// Structs are stored inline, so nothing additional is being added.
511	// In generated code, `d` is always 0.
512	pub fn prependSlotStruct(b: *Builder, voffset: u32, x: u32, d: u32) !void {
513	    if (x != d) {
514	        try b.checkNested();
515	        if (x != b.offset()) return err(
516	            "inline data write outside of object",
517	            .{},
518	            error.InvalidOffset,
519	        );
520	        b.slot(voffset);
521	    }
522	}
523	
524	/// sets the vtable key `voffset` to the current location in the buffer.
525	pub fn slot(b: *Builder, slotnum: u32) void {
526	    b.vtable.items[slotnum] = b.offset();
527	}
528	
529	/// finalizes a buffer, pointing to the given `rootTable`.
530	/// as well as applys a file identifier
531	pub fn finishWithFileIdentifier(b: *Builder, rootTable: u32, fid: Fid) !void {
532	    // In order to add a file identifier to the flatbuffer message, we need
533	    // to prepare an alignment and file identifier length
534	    try b.prep(@bitCast(b.minalign), size_i32 + file_identifier_len);
535	    var i = file_identifier_len - 1;
536	    while (i >= 0) : (i -= 1) {
537	        // place the file identifier
538	        b.place(u8, fid[@as(u32, @bitCast(i))]);
539	    }
540	    // finish
541	    return b.finish(rootTable);
542	}
543	
544	/// finalizes a buffer, pointing to the given `rootTable`.
545	/// The buffer is prefixed with the size of the buffer, excluding the size
546	/// of the prefix itself.
547	pub fn finishSizePrefixed(b: *Builder, rootTable: u32) !void {
548	    return b.finishPrefixed(rootTable, true);
549	}
550	
551	/// finalizes a buffer, pointing to the given `rootTable`
552	/// and applies a file identifier. The buffer is prefixed with the size of the buffer,
553	/// excluding the size of the prefix itself.
554	pub fn finishSizePrefixedWithFileIdentifier(b: *Builder, rootTable: u32, fid: [4]u8) !void {
555	    // In order to add a file identifier and size prefix to the flatbuffer message,
556	    // we need to prepare an alignment, a size prefix length, and file identifier length
557	    try b.prep(@bitCast(b.minalign), size_i32 + file_identifier_len + size_prefix_length);
558	    var i = file_identifier_len - 1;
559	    while (i >= 0) : (i -= 1) {
560	        // place the file identifier
561	        b.place(u8, fid[@as(u32, @bitCast(i))]);
562	    }
563	    // finish
564	    return b.finishPrefixed(rootTable, true);
565	}
566	
567	/// finalizes a buffer, pointing to the given `rootTable`.
568	pub fn finish(b: *Builder, rootTable: u32) !void {
569	    try b.finishPrefixed(rootTable, false);
570	}
571	
572	/// finalizes a buffer, pointing to the given `rootTable`
573	/// with a size prefix.
574	pub fn finishPrefixed(b: *Builder, root_table: u32, size_prefix: bool) !void {
575	    try b.checkNotNested();
576	
577	    if (size_prefix)
578	        try b.prep(@bitCast(b.minalign), size_u32 + size_prefix_length)
579	    else
580	        try b.prep(@bitCast(b.minalign), size_u32);
581	
582	    try b.prependUOff(root_table);
583	    if (size_prefix) b.place(u32, b.offset());
584	    b.finished = true;
585	}
586	
587	/// compares an unwritten vtable to a written vtable.
588	pub fn vtableEqual(a: []const u32, objectStart: u32, b: []const u8) bool {
589	    if (a.len * size_u16 != b.len) return false;
590	
591	    for (0..a.len) |i| {
592	        const x = read(u16, b[i * size_u16 .. (i + 1) * size_u16]);
593	
594	        // Skip vtable entries that indicate a default value.
595	        if (x == 0 and a[i] == 0) continue;
596	
597	        const y = objectStart - a[i];
598	        if (x != y) return false;
599	    }
600	    return true;
601	}
602	
603	/// prepends a T to the Builder buffer.
604	/// Aligns and checks for space.
605	pub fn prepend(b: *Builder, comptime T: type, x: T) !void {
606	    try b.prep(@sizeOf(T), 0);
607	    b.place(T, x);
608	}
609	
610	/// prepends a T to the Builder, without checking for space.
611	pub fn place(b: *Builder, comptime T: type, x: T) void {
612	    b.debug("place{s} b.head={} x={}", .{ @typeName(T), b.head, x });
613	    b.head -= @sizeOf(T);
614	    write(T, b.bytes.items[b.head..], x);
615	}
