4	pub const Error = error{
5	    InvalidMetadata,
6	};
7	
8	pub const MessageEnvelope = struct {
9	    version: i16,
10	    header_type: u8,
11	    body_length: i64,
12	};
13	
14	/// Fast structural sanity check for any FlatBuffer table blob.
15	pub fn isSaneTable(buf: []const u8) bool {
16	    _ = reader.rootTable(buf) catch return false;
17	    return true;
18	}
19	
20	/// Parse + validate Arrow IPC Message envelope fields without full unpack.
21	///
22	/// Message.fbs field ids:
23	/// 0 = version (enum MetadataVersion: short)
24	/// 1 = header_type (union discriminator)
25	/// 3 = bodyLength (long)
26	pub fn parseArrowMessageEnvelope(buf: []const u8) Error!MessageEnvelope {
27	    const table = reader.rootTable(buf) catch return error.InvalidMetadata;
28	
29	    const version = table.readFieldI16(0) orelse 0;
30	    if (version < 0 or version > 4) return error.InvalidMetadata;
31	
32	    const header_type = table.readFieldU8(1) orelse return error.InvalidMetadata;
33	    if (header_type == 0) return error.InvalidMetadata;
34	
35	    const body_length = table.readFieldI64(3) orelse 0;
36	
37	    return .{
38	        .version = version,
39	        .header_type = header_type,
40	        .body_length = body_length,
41	    };
42	}
