119	/// initializes bookkeeping for writing a new object.
120	pub fn startObject(b: *Builder, numfields: u32) !void {
121	    try b.checkNotNested();
122	    b.nested = true;
123	    try b.vtable.ensureTotalCapacity(b.alloc, numfields);
124	    b.vtable.items.len = numfields;
125	    @memset(b.vtable.items, 0);
