293	/// prepares to write an element of `size` after `additional_bytes`
294	/// have been written, e.g. if you write a []const u8, you need to align such
295	/// the int length field is aligned to size_i32, and the []const u8 data follows it
296	/// directly.
297	/// If all you need to do is align, `additional_bytes` will be 0.
298	pub fn prep(b: *Builder, size: i32, additional_bytes: i32) !void {
299	    // Track the biggest thing we've ever aligned to.
300	    if (size > b.minalign) b.minalign = @bitCast(size);
301	
302	    // Find the amount of alignment needed such that `size` is properly
303	    // aligned after `additional_bytes`:
304	    var align_size = (~(@as(i64, @bitCast(b.bytes.items.len)) - @as(i32, @bitCast(b.head)) + additional_bytes) + 1);
305	    align_size &= size - 1;
306	
307	    b.debug("prep() 1 b.head={} align_size={} additional_bytes={} size={}", .{ b.head, align_size, additional_bytes, size });
308	    // Reallocate the buffer if needed:
309	    while (b.head <= align_size + size + additional_bytes) {
310	        const old_buf_size = b.bytes.items.len;
311	        try b.growByteBuffer();
312	        b.head += @intCast(b.bytes.items.len - old_buf_size);
313	    }
314	    b.pad(@intCast(align_size));
315	    b.debug("prep() b.head={} bytes.len={}", .{ b.head, b.bytes.items.len });
316	}
317	
318	/// prepends a i32, relative to where it will be written.
319	pub fn prependSOff(b: *Builder, off: i32) !void {
320	    try b.prep(size_i32, 0); // Ensure alignment is already done.
321	    if (off > b.offset())
322	        return err("unreachable: off > b.offset()", .{}, error.InvalidOffset);
323	
324	    const off2 = @as(i32, @bitCast(b.offset())) - off + size_i32;
325	    b.place(i32, off2);
326	}
327	
328	/// prepends a u32, relative to where it will be written.
329	pub fn prependUOff(b: *Builder, off: u32) !void {
330	    b.debug("prependUOff off={}", .{off});
331	    try b.prep(size_u32, 0); // Ensure alignment is already done.
332	    if (off > b.offset())
333	        return err("unreachable: off > b.offset()", .{}, error.InvalidOffset);
334	
335	    const off2 = b.offset() - off + size_u32;
336	    b.place(u32, off2);
337	}
