339	/// initializes bookkeeping for writing a new vector.
340	///
341	/// A vector has the following format:
342	///   <u32: number of elements in this vector>
343	///   <T: data>+, where T is the type of elements of this vector.
344	pub fn startVector(b: *Builder, elem_size: i32, num_elems: i32, alignment: i32) !u32 {
345	    try b.checkNotNested();
346	    b.nested = true;
347	    try b.prep(size_u32, elem_size * num_elems);
348	    try b.prep(alignment, elem_size * num_elems); // Just in case alignment > int.
349	    return b.offset();
350	}
351	
352	/// writes data necessary to finish vector construction.
353	pub fn endVector(b: *Builder, vector_num_elems: u32) !u32 {
354	    try b.checkNested();
