459	fn checkNotNested(b: *Builder) !void {
460	    // If you hit this, you're trying to construct a Table/Vector/String
461	    // during the construction of its parent table (between the MyTableBuilder
462	    // and builder.Finish()).
463	    // Move the creation of these sub-objects to above the MyTableBuilder to
464	    // not get this assert.
465	    // Ignoring this error may appear to work in simple cases, but the reason
466	    // it is here is that storing objects in-line may cause vtable offsets
467	    // to not fit anymore. It also leads to vtable duplication.
468	    if (b.nested) return err(
469	        "Incorrect creation order: object must not be nested.",
