531	pub fn finishWithFileIdentifier(b: *Builder, rootTable: u32, fid: Fid) !void {
532	    // In order to add a file identifier to the flatbuffer message, we need
533	    // to prepare an alignment and file identifier length
534	    try b.prep(@bitCast(b.minalign), size_i32 + file_identifier_len);
535	    var i = file_identifier_len - 1;
