328	fn writeMessage(allocator: std.mem.Allocator, writer: *std.Io.Writer, msg: fbs.MessageT, body_buffers: []const array_data.SharedBuffer) (WriterError || std.Io.Writer.Error)!void {
329	    const metadata = try fbs_lite_builder.packMessageBytes(allocator, msg);
330	    defer allocator.free(metadata);
331	
332	    // IPC stream framing stores the padded metadata length in the prefix.
333	    const metadata_len = format.paddedLen(metadata.len);
334	    try format.writeMessageLength(writer, try castU32Metadata(metadata_len));
335	    try writer.writeAll(metadata);
336	    try format.writePadding(writer, format.padLen(metadata.len));
337	
338	    var pad_bytes: [format.Alignment]u8 = @splat(0);
339	    for (body_buffers) |buf| {
340	        if (buf.len() > 0) try writer.writeAll(buf.data);
341	        const pad_len = format.padLen(buf.len());
342	        if (pad_len > 0) try writer.writeAll(pad_bytes[0..pad_len]);
343	    }
344	}
