966	fn planDictionaryEmission(
967	    previous_opt: ?ArrayRef,
968	    current: ArrayRef,
969	) (StreamError || error{OutOfMemory})!DictionaryEmission {
970	    if (previous_opt == null) {
971	        return .{ .mode = .full, .array = current };
972	    }
973	    const previous = previous_opt.?;
974	    if (!datatype.dataTypeEql(previous.data().data_type, current.data().data_type)) return StreamError.InvalidMetadata;
975	
976	    if (previous.data().length == current.data().length) {
977	        if (try arraysEqualForDelta(previous, current)) {
978	            return .{ .mode = .skip, .array = current };
979	        }
980	        return .{ .mode = .full, .array = current };
981	    }
982	    if (current.data().length < previous.data().length) {
983	        return .{ .mode = .full, .array = current };
984	    }
985	    if (!supportsDictionaryDeltaType(current.data().data_type)) {
986	        return .{ .mode = .full, .array = current };
987	    }
988	
989	    var prefix = try current.slice(0, previous.data().length);
990	    defer prefix.release();
991	    if (!try arraysEqualForDelta(previous, prefix)) {
992	        return .{ .mode = .full, .array = current };
993	    }
994	
995	    const delta_len = current.data().length - previous.data().length;
996	    if (delta_len == 0) {
997	        return .{ .mode = .skip, .array = current };
998	    }
999	    const tail = try current.slice(previous.data().length, delta_len);
1000	    return .{ .mode = .delta, .array = tail, .owned_slice = tail };
1001	}
