1155	    try nodes.append(allocator, .{
1156	        .length = try castI64Metadata(data.length),
1157	        .null_count = try castI64Metadata(null_count),
1158	    });
1159	    const layout_dt = storageDataType(data.data_type);
1160	
1161	    if (metadata_version == .v4 and (layout_dt == .sparse_union or layout_dt == .dense_union)) {
1162	        // V4 union layout includes an explicit validity bitmap buffer.
1163	        // We don't currently model union nulls, so emit a 0-byte bitmap when null_count==0.
1164	        try buffers.append(allocator, .{
1165	            .offset = try castI64Metadata(body_offset.*),
1166	            .length = 0,
1167	        });
1168	        try body_buffers.append(allocator, array_data.SharedBuffer.empty);
1169	    }
1170	
1171	    for (data.buffers) |buf| {
1172	        try buffers.append(allocator, .{
1173	            .offset = try castI64Metadata(body_offset.*),
1174	            .length = try castI64Metadata(buf.len()),
1175	        });
1176	        try body_buffers.append(allocator, buf);
1177	        body_offset.* = std.math.add(u64, body_offset.*, format.paddedLen(buf.len())) catch return StreamError.InvalidMetadata;
1178	    }
1179	    if (layout_dt == .string_view or layout_dt == .binary_view) {
1180	        if (data.buffers.len < 2) return StreamError.InvalidMetadata;
1181	        const variadic_count = std.math.sub(usize, data.buffers.len, 2) catch return StreamError.InvalidMetadata;
1182	        try variadic_buffer_counts.append(allocator, try castI64Metadata(variadic_count));
1183	    }
1184	
1185	    switch (layout_dt) {
1186	        .list, .large_list, .fixed_size_list, .map, .list_view, .large_list_view => {
1187	            if (data.children.len != 1) return StreamError.InvalidMetadata;
1188	            try appendArrayMeta(allocator, data.children[0].data(), nodes, buffers, variadic_buffer_counts, body_buffers, body_offset, metadata_version);
1189	        },
1190	        .struct_ => {
1191	            for (data.children) |child| {
1192	                try appendArrayMeta(allocator, child.data(), nodes, buffers, variadic_buffer_counts, body_buffers, body_offset, metadata_version);
1193	            }
1194	        },
1195	        .sparse_union, .dense_union => {
1196	            for (data.children) |child| {
1197	                try appendArrayMeta(allocator, child.data(), nodes, buffers, variadic_buffer_counts, body_buffers, body_offset, metadata_version);
1198	            }
1199	        },
1200	        .run_end_encoded => |ree| {
1201	            _ = ree;
1202	            if (data.buffers.len != 0) return StreamError.InvalidMetadata;
1203	            if (data.children.len != 2) return StreamError.InvalidMetadata;
1204	            try appendArrayMeta(allocator, data.children[0].data(), nodes, buffers, variadic_buffer_counts, body_buffers, body_offset, metadata_version);
1205	            try appendArrayMeta(allocator, data.children[1].data(), nodes, buffers, variadic_buffer_counts, body_buffers, body_offset, metadata_version);
1206	        },
1207	        .dictionary => {},
1208	        else => {},
1209	    }
1210	}
