1212	fn applyBodyCompression(
1213	    allocator: std.mem.Allocator,
1214	    codec: BodyCompressionCodec,
1215	    buffers: *std.ArrayList(fbs.BufferT),
1216	    body_buffers: *std.ArrayList(array_data.SharedBuffer),
1217	    body_offset: *u64,
1218	) WriterError!*fbs.BodyCompressionT {
1219	    if (buffers.items.len != body_buffers.items.len) return StreamError.InvalidMetadata;
1220	
1221	    const original = try allocator.dupe(array_data.SharedBuffer, body_buffers.items);
1222	    defer allocator.free(original);
1223	
1224	    body_buffers.clearRetainingCapacity();
1225	    var cursor: u64 = 0;
1226	
1227	    for (original, 0..) |src, i| {
1228	        if (src.len() == 0) {
1229	            buffers.items[i] = .{ .offset = try castI64Metadata(cursor), .length = 0 };
1230	            try body_buffers.append(allocator, array_data.SharedBuffer.empty);
1231	            continue;
1232	        }
1233	
1234	        const compressed_payload = try compressBodyBufferPayload(allocator, codec, src.data);
1235	        defer allocator.free(compressed_payload);
1236	        const encoded_len = std.math.add(usize, 8, compressed_payload.len) catch return StreamError.InvalidMetadata;
1237	        var encoded = try buffer.OwnedBuffer.init(allocator, encoded_len);
1238	        errdefer encoded.deinit();
1239	
1240	        var header: [8]u8 = undefined;
1241	        std.mem.writeInt(i64, &header, try castI64Metadata(src.len()), .little);
1242	        @memcpy(encoded.data[0..8], header[0..]);
1243	        @memcpy(encoded.data[8..encoded_len], compressed_payload);
1244	
1245	        const shared = try encoded.toShared(encoded_len);
1246	        try body_buffers.append(allocator, shared);
1247	        buffers.items[i] = .{
1248	            .offset = try castI64Metadata(cursor),
1249	            .length = try castI64Metadata(encoded_len),
1250	        };
1251	        cursor = std.math.add(u64, cursor, format.paddedLen(encoded_len)) catch return StreamError.InvalidMetadata;
1252	    }
1253	
1254	    body_offset.* = cursor;
1255	
1256	    const compression_ptr = try allocator.create(fbs.BodyCompressionT);
1257	    compression_ptr.* = .{
1258	        .codec = switch (codec) {
1259	            .lz4_frame => .LZ4_FRAME,
1260	            .zstd => .ZSTD,
1261	        },
1262	        .method = .BUFFER,
1263	    };
1264	    return compression_ptr;
1265	}
