1267	fn compressBodyBufferPayload(
1268	    allocator: std.mem.Allocator,
1269	    codec: BodyCompressionCodec,
1270	    input: []const u8,
1271	) (WriterError || error{OutOfMemory})![]u8 {
1272	    return switch (codec) {
1273	        .zstd => try compressZstdPayload(allocator, input),
1274	        .lz4_frame => try compressLz4FramePayload(allocator, input),
1275	    };
1276	}
1277	
1278	fn compressZstdPayload(
1279	    allocator: std.mem.Allocator,
1280	    input: []const u8,
1281	) (WriterError || error{OutOfMemory})![]u8 {
1282	    const syms = compression_dynlib.loadZstdSymbols() catch return StreamError.UnsupportedType;
1283	
1284	    const bound = syms.*.compress_bound(input.len);
1285	    if (bound == 0) return StreamError.InvalidMetadata;
1286	    const out = try allocator.alloc(u8, bound);
1287	    errdefer allocator.free(out);
1288	
1289	    const written = syms.*.compress(
1290	        @ptrCast(out.ptr),
1291	        out.len,
1292	        if (input.len == 0) null else @ptrCast(input.ptr),
1293	        input.len,
1294	        1,
1295	    );
1296	    if (syms.*.is_error(written) != 0) return StreamError.InvalidMetadata;
1297	    if (written == 0 or written > out.len) return StreamError.InvalidMetadata;
1298	    return try allocator.realloc(out, written);
1299	}
