1301	fn compressLz4FramePayload(
1302	    allocator: std.mem.Allocator,
1303	    input: []const u8,
1304	) (WriterError || error{OutOfMemory})![]u8 {
1305	    const syms = compression_dynlib.loadLz4Symbols() catch return StreamError.UnsupportedType;
1306	
1307	    const bound = syms.*.compress_frame_bound(input.len, null);
1308	    if (bound == 0 or syms.*.is_error(bound) != 0) return StreamError.InvalidMetadata;
1309	    const out = try allocator.alloc(u8, bound);
1310	    errdefer allocator.free(out);
1311	
1312	    const written = syms.*.compress_frame(
1313	        @ptrCast(out.ptr),
1314	        out.len,
1315	        if (input.len == 0) null else @ptrCast(input.ptr),
1316	        input.len,
1317	        null,
1318	    );
1319	    if (syms.*.is_error(written) != 0) return StreamError.InvalidMetadata;
1320	    if (written == 0 or written > out.len) return StreamError.InvalidMetadata;
1321	    return try allocator.realloc(out, written);
1322	}
