216	    pub fn writeRecordBatch(self: *Self, batch: RecordBatch) (WriterError || std.Io.Writer.Error)!void {
217	        var dictionary_ids = try std.ArrayList(i64).initCapacity(self.allocator, 0);
218	        defer dictionary_ids.deinit(self.allocator);
219	        var next_dictionary_id: i64 = 0;
220	        for (batch.schema().fields) |field| {
221	            try collectDictionaryIdsFromField(self.allocator, field, &next_dictionary_id, &dictionary_ids);
222	        }
223	
224	        var dictionary_arrays = try std.ArrayList(ArrayRef).initCapacity(self.allocator, 0);
225	        defer {
226	            for (dictionary_arrays.items) |dict_ref| {
227	                var owned = dict_ref;
228	                owned.release();
229	            }
230	            dictionary_arrays.deinit(self.allocator);
231	        }
232	        for (batch.columns) |col| {
233	            try collectDictionaryArraysFromData(self.allocator, col.data(), &dictionary_arrays);
234	        }
235	        if (dictionary_ids.items.len != dictionary_arrays.items.len) return StreamError.InvalidMetadata;
236	
237	        for (dictionary_ids.items, dictionary_arrays.items) |dictionary_id, dict_ref| {
238	            const emission = try planDictionaryEmission(self.dictionary_values.get(dictionary_id), dict_ref);
239	            if (emission.mode != .skip) {
240	                try writeDictionaryBatch(
241	                    self.allocator,
242	                    self.writer,
243	                    dictionary_id,
244	                    emission.array.data(),
245	                    emission.mode == .delta,
246	                    self.metadata_version,
247	                );
248	            }
249	            if (emission.owned_slice) |slice| {
250	                var owned = slice;
251	                owned.release();
252	            }
253	
254	            const previous = try self.dictionary_values.fetchPut(dictionary_id, dict_ref.retain());
255	            if (previous) |entry| {
256	                var old = entry.value;
257	                old.release();
258	            }
259	        }
260	
261	        var nodes = try std.ArrayList(fbs.FieldNodeT).initCapacity(self.allocator, 0);
262	        var buffers = try std.ArrayList(fbs.BufferT).initCapacity(self.allocator, 0);
263	        var variadic_buffer_counts = try std.ArrayList(i64).initCapacity(self.allocator, 0);
264	        var body_buffers = try std.ArrayList(array_data.SharedBuffer).initCapacity(self.allocator, 0);
265	        var owns_body_buffers = false;
266	        defer body_buffers.deinit(self.allocator);
267	        defer if (owns_body_buffers) {
268	            for (body_buffers.items) |buf| {
269	                var owned = buf;
270	                owned.release();
271	            }
272	        };
273	
274	        var body_offset: u64 = 0;
275	        for (batch.columns) |col| {
276	            try appendArrayMeta(
277	                self.allocator,
278	                col.data(),
279	                &nodes,
280	                &buffers,
281	                &variadic_buffer_counts,
282	                &body_buffers,
283	                &body_offset,
284	                self.metadata_version,
285	            );
286	        }
287	
288	        var compression_ptr: ?*fbs.BodyCompressionT = null;
289	        if (self.body_compression) |codec| {
290	            compression_ptr = try applyBodyCompression(
291	                self.allocator,
292	                codec,
293	                &buffers,
294	                &body_buffers,
295	                &body_offset,
296	            );
297	            owns_body_buffers = true;
298	        }
299	
300	        const record_batch_ptr = try self.allocator.create(fbs.RecordBatchT);
301	        errdefer self.allocator.destroy(record_batch_ptr);
302	        record_batch_ptr.* = .{
303	            .length = try castI64Metadata(batch.numRows()),
304	            .nodes = nodes,
305	            .buffers = buffers,
306	            .compression = compression_ptr,
307	            .variadicBufferCounts = variadic_buffer_counts,
308	        };
309	
310	        var msg = fbs.MessageT{
311	            .version = toFbsMetadataVersion(self.metadata_version),
312	            .header = .{ .RecordBatch = record_batch_ptr },
313	            .bodyLength = try castI64Metadata(body_offset),
314	            .custom_metadata = try std.ArrayList(fbs.KeyValueT).initCapacity(self.allocator, 0),
315	        };
316	        defer msg.deinit(self.allocator);
317	
318	        try writeMessage(self.allocator, self.writer, msg, body_buffers.items);
319	    }
