824	fn collectDictionaryIdsFromField(
825	    allocator: std.mem.Allocator,
826	    field: Field,
827	    next_dictionary_id: *i64,
828	    ids: *std.ArrayList(i64),
829	) error{OutOfMemory}!void {
830	    switch (field.data_type.*) {
831	        .dictionary => |dict| {
832	            const dictionary_id = dict.id orelse id_blk: {
833	                const assigned = next_dictionary_id.*;
834	                next_dictionary_id.* += 1;
835	                break :id_blk assigned;
836	            };
837	            try ids.append(allocator, dictionary_id);
838	        },
839	        .list => |lst| try collectDictionaryIdsFromField(allocator, lst.value_field, next_dictionary_id, ids),
840	        .large_list => |lst| try collectDictionaryIdsFromField(allocator, lst.value_field, next_dictionary_id, ids),
841	        .list_view => |lst| try collectDictionaryIdsFromField(allocator, lst.value_field, next_dictionary_id, ids),
842	        .large_list_view => |lst| try collectDictionaryIdsFromField(allocator, lst.value_field, next_dictionary_id, ids),
843	        .fixed_size_list => |lst| try collectDictionaryIdsFromField(allocator, lst.value_field, next_dictionary_id, ids),
844	        .map => |map_t| {
845	            try collectDictionaryIdsFromField(allocator, map_t.key_field, next_dictionary_id, ids);
846	            try collectDictionaryIdsFromField(allocator, map_t.item_field, next_dictionary_id, ids);
847	        },
848	        .struct_ => |st| for (st.fields) |child| try collectDictionaryIdsFromField(allocator, child, next_dictionary_id, ids),
849	        .sparse_union, .dense_union => |uni| for (uni.fields) |child| try collectDictionaryIdsFromField(allocator, child, next_dictionary_id, ids),
850	        .run_end_encoded => |ree| {
851	            const value_field = Field{
852	                .name = "values",
853	                .data_type = ree.value_type,
854	                .nullable = true,
855	            };
856	            try collectDictionaryIdsFromField(allocator, value_field, next_dictionary_id, ids);
857	        },
858	        .extension => |ext| {
859	            const storage_field = Field{
860	                .name = field.name,
861	                .data_type = ext.storage_type,
862	                .nullable = field.nullable,
863	                .metadata = field.metadata,
864	            };
865	            try collectDictionaryIdsFromField(allocator, storage_field, next_dictionary_id, ids);
866	        },
867	        else => {},
868	    }
869	}
