879	            try out.append(allocator, data.dictionary.?.retain());
880	        },
881	        .list, .large_list, .fixed_size_list, .list_view, .large_list_view => {
882	            if (data.children.len == 1) try collectDictionaryArraysFromData(allocator, data.children[0].data(), out);
