884	        .map => {
885	            if (data.children.len == 1) try collectDictionaryArraysFromData(allocator, data.children[0].data(), out);
886	        },
887	        .run_end_encoded => {
888	            if (data.children.len == 2) try collectDictionaryArraysFromData(allocator, data.children[1].data(), out);
889	        },
890	        .struct_ => {
891	            for (data.children) |child| try collectDictionaryArraysFromData(allocator, child.data(), out);
892	        },
893	        .sparse_union, .dense_union => {
894	            for (data.children) |child| try collectDictionaryArraysFromData(allocator, child.data(), out);
895	        },
896	        else => {},
897	    }
