165	    fn flushPendingMessages(self: *Self, final: bool) (FileError || std.Io.Writer.Error)!void {
166	        // Parse complete messages out of `pending` by offset; drop the consumed prefix once at exit.
167	        const bytes = self.pending.written();
168	        var pos: usize = 0;
169	        defer self.pending.clearRetainingCapacity();
170	
171	        while (pos < bytes.len) {
172	            const rest = bytes[pos..];
173	            if (rest.len < 4) return error.InvalidMessage;
174	
175	            const first = readU32Le(rest[0..4]);
176	            var prefix_len: usize = 4;
177	            var metadata_len_u32 = first;
178	            if (first == format.ContinuationMarker) {
179	                if (rest.len < 8) return error.InvalidMessage;
180	                metadata_len_u32 = readU32Le(rest[4..8]);
181	                prefix_len = 8;
182	                if (metadata_len_u32 == 0) {
183	                    if (!final) return error.InvalidMessage;
184	                    self.saw_stream_end = true;
185	                    pos += 8;
186	                    continue;
187	                }
188	            } else if (first == 0) {
189	                if (!final) return error.InvalidMessage;
190	                self.saw_stream_end = true;
191	                pos += 4;
192	                continue;
193	            }
194	
195	            const metadata_len = std.math.cast(usize, metadata_len_u32) orelse return error.InvalidMessage;
196	            const needed_metadata = std.math.add(usize, prefix_len, metadata_len) catch return error.InvalidMessage;
197	            if (rest.len < needed_metadata) return error.InvalidMessage;
198	
199	            const metadata = rest[prefix_len..needed_metadata];
200	            const envelope = fbs_lite_verify.parseArrowMessageEnvelope(metadata) catch return error.InvalidMessage;
201	            if (envelope.body_length < 0) return error.InvalidMessage;
202	            const body_len = std.math.cast(usize, envelope.body_length) orelse return error.InvalidMessage;
203	            var msg_t = try fbs_lite_builder.unpackMessage(self.allocator, metadata);
204	            defer msg_t.deinit(self.allocator);
205	
206	            if (msg_t.bodyLength != envelope.body_length) return error.InvalidMessage;
207	            const body_pad = format.padLen(body_len);
208	            const body_total = std.math.add(usize, body_len, body_pad) catch return error.InvalidMessage;
209	            const message_total = std.math.add(usize, needed_metadata, body_total) catch return error.InvalidMessage;
210	            if (rest.len < message_total) return error.InvalidMessage;
211	
212	            switch (msg_t.header) {
213	                .Schema => {
214	                    if (self.schema_msg != null) return error.InvalidMessage;
215	                    const metadata_copy = try self.allocator.dupe(u8, metadata);
216	                    errdefer self.allocator.free(metadata_copy);
217	                    var schema_msg_t = try fbs_lite_builder.unpackMessage(self.allocator, metadata_copy);
218	                    errdefer schema_msg_t.deinit(self.allocator);
219	                    if (schema_msg_t.header != .Schema) return error.InvalidMessage;
220	                    const owned_msg = try self.allocator.create(fbs.MessageT);
221	                    owned_msg.* = schema_msg_t;
222	                    self.schema_msg = owned_msg;
223	                    self.schema_metadata_bytes = metadata_copy;
224	                },
225	                .DictionaryBatch, .RecordBatch => {
226	                    const file_offset = std.math.cast(i64, FileMagic.len + 2 + self.stream_offset) orelse return error.InvalidMessage;
227	                    const meta_data_length = std.math.cast(i32, prefix_len + format.paddedLen(metadata_len)) orelse return error.InvalidMessage;
228	                    const block = fbs.BlockT{
229	                        .offset = file_offset,
230	                        .metaDataLength = meta_data_length,
231	                        .bodyLength = envelope.body_length,
232	                    };
233	                    if (msg_t.header == .DictionaryBatch) {
234	                        try self.dictionary_blocks.append(self.allocator, block);
235	                    } else {
236	                        try self.record_batch_blocks.append(self.allocator, block);
237	                    }
238	                },
239	                .Tensor, .SparseTensor => {
240	                    const file_offset = std.math.cast(i64, FileMagic.len + 2 + self.stream_offset) orelse return error.InvalidMessage;
241	                    const meta_data_length = std.math.cast(i32, prefix_len + format.paddedLen(metadata_len)) orelse return error.InvalidMessage;
242	                    const block = fbs.BlockT{
243	                        .offset = file_offset,
244	                        .metaDataLength = meta_data_length,
245	                        .bodyLength = envelope.body_length,
246	                    };
247	                    if (msg_t.header == .Tensor) {
248	                        try self.tensor_blocks.append(self.allocator, block);
249	                    } else {
250	                        try self.sparse_tensor_blocks.append(self.allocator, block);
251	                    }
252	                },
253	                else => return error.UnsupportedMessage,
254	            }
255	
256	            try self.ensureHeaderWritten();
257	            try self.writer.writeAll(rest[0..message_total]);
258	            self.stream_offset = std.math.add(usize, self.stream_offset, message_total) catch return error.InvalidMessage;
259	            pos += message_total;
260	        }
261	    }
