127	        if (self.finished) return FileError.AlreadyFinished;
128	        if (self.failed) return FileError.InvalidState;
129	        errdefer self.failed = true;
130	        self.stream.writeEnd() catch |e| return if (e == error.WriteFailed) error.OutOfMemory else e;
131	        try self.flushPendingMessages(true);
