191	    fn ensureLoaded(self: *Self) FileError!void {
192	        if (self.loaded) return;
193	
194	        const header_len = FileMagic.len + 2;
195	        const trailer_len = 4 + FileMagic.len;
196	        const file_len = self.bytes.len;
197	        if (file_len < header_len + trailer_len) return error.InvalidFile;
198	
199	        var header_magic: [FileMagic.len]u8 = undefined;
200	        try self.readAtNoEof(0, header_magic[0..]);
201	        if (!std.mem.eql(u8, header_magic[0..], FileMagic)) return error.InvalidFile;
202	
203	        var trailer: [4 + FileMagic.len]u8 = undefined;
204	        const footer_len_pos = file_len - trailer_len;
205	        try self.readAtNoEof(footer_len_pos, trailer[0..]);
206	        if (!std.mem.eql(u8, trailer[4..], FileMagic)) return error.InvalidFile;
207	
208	        const footer_len_u32 = readU32Le(trailer[0..4]);
209	        const footer_len = std.math.cast(usize, footer_len_u32) orelse return error.FooterTooLarge;
210	        const footer_end = footer_len_pos;
211	        if (footer_len > footer_end - header_len) return error.InvalidFile;
212	        const footer_start = footer_end - footer_len;
213	        if (footer_start < header_len) return error.InvalidFile;
214	
215	        const footer_bytes = try self.allocator.alloc(u8, footer_len);
216	        defer self.allocator.free(footer_bytes);
217	        try self.readAtNoEof(footer_start, footer_bytes);
218	        if (!fbs_lite_verify.isSaneTable(footer_bytes)) return error.InvalidFile;
219	
220	        var footer_t = try fbs_lite_builder.unpackFooter(self.allocator, footer_bytes);
221	        defer footer_t.deinit(self.allocator);
222	        if (footer_t.schema == null) return error.InvalidFile;
223	
224	        self.indexed = try self.buildIndexedFromFooter(footer_t, header_len, footer_start);
225	
226	        var arena = std.heap.ArenaAllocator.init(self.allocator);
227	        errdefer arena.deinit();
228	        const schema = try stream_reader.buildSchemaFromFlatbufWithEndiannessMode(
229	            arena.allocator(),
230	            footer_t.schema.?,
231	            self.options.endianness_mode,
232	        );
233	        self.schema_ref = try SchemaRef.fromArena(self.allocator, arena, schema);
234	
235	        self.resetDecodeState();
236	        self.loaded = true;
237	    }
